export const templatePreview: Promise<TemplatePreview> = admin.notification.template.preview({ tenant_id, id: "template", language: "bs" });
export const templateTest: Promise<OutgoingMessage> = admin.notification.template.test({ tenant_id, id: "template", outgoing_message_id: "8a6d4f2b-9c1e-4e57-b3a8-1f6c9e2d4b70", language: "bs", email_address_id: "4b6d8f0a-2e3a-4b7d-9f1c-3e5a7b9d1f2a", from_name: "Shop", reply_to_address_id: "4b6d8f0a-2e3a-4b7d-9f1c-3e5a7b9d1f2a" });
